function wireListSearch(inputId, itemSelector, countId){const input=$('#'+inputId),items=[...app.querySelectorAll(itemSelector)],count=$('#'+countId);if(!input)return;const update=()=>{const q=input.value.trim().toLowerCase().split(/\s+/).filter(Boolean);let visible=0;items.forEach(item=>{const hay=(item.dataset.search||item.textContent||'').toLowerCase();const show=q.every(token=>hay.includes(token));item.hidden=!show;if(show)visible++});if(count)count.textContent=`${visible} result${visible===1?'':'s'}`};input.addEventListener('input',update);update()}
